      hyobs:hasRiverBasedRegion ?region ;
      hyobs:monitorsCatchment ?sensor ;
      hyobs:hasMeanDailyPrecip ?meanDailyPrecip ;

      sosa:madeBySensor ?sensor ;
      sosa:observedProperty hyobs:hasMeanDailyPrecip .

