         sosa:observedProperty hyobs:hasMeanDailyPrecip ;
         sosa:resultTime ?rt ;
         sosa:hasSimpleResult ?qv ;
         dct:identifier ?obsId .

    ?qv qudt:numericValue ?meanDailyPrecValue .

    ?sensor a sosa:Sensor ;
      esco:isoCountryCodeA3 ?countryCode .

    FILTER(?countryCode = "AUT") .
    FILTER(YEAR(?rt) = 2010) .

    BIND((?meanDailyPrecValue * 365.0) AS ?precipTotal)
    FILTER(?precipTotal > 1000.0) .

    BIND(?catchment AS ?catchment)
  }
}
GROUP BY ?catchment ?precipTotal
ORDER BY DESC(?precipTotal)

